W += [
E('countersign','英 /ˈkaʊntəsaɪn/；美 /ˈkaʊntərsaɪn/','副署；会签；口令、应答暗号','countersign 有两个相关画面：别人的签名旁边再签一次作确认；卫兵发问后，来人报出约定的应答口令。','动词借法语 contresigner，名词借 contresigne；现代可分析 counter- + sign，但两种词性有各自法语形式。',COUNTER,'countersign a document 是在已签文件上加签；give the countersign 是说出口令。counter- 这里是回应、相对，不是反对签名。','countersign a form；give the countersign；request a countersignature。','sign 是签；countersign 通常是在已有签名之外加签确认。具体程序作用要看文件要求。',('The supervisor countersigned the completed form.','主管在填写完的表格上加签确认。'),('The guard waited for the correct countersign.','卫兵等着对方说出正确的口令。'),sources=['https://www.etymonline.com/word/countersign','https://www.merriam-webster.com/dictionary/countersign']),
E('countersignature','英 /ˌkaʊntəˈsɪɡnətʃə/；美 /ˌkaʊntərˈsɪɡnətʃər/','副署；会签；追加确认的签名','countersignature 就是别人签过之后，加在旁边用来确认的那一个签名。','现代可拆 counter- + signature；词典也明确分析为 countersign 仿照 sign / signature 这一对词形成。',COUNTER+[['英语类比：sign : signature → countersign : countersignature','照已有动词、名词搭配构成追加签名的名词']],'the manager’s countersignature 是经理追加的签字；a space for a countersignature 是为副署留的位置。','require a countersignature；add a countersignature；a countersignature box。','signature 是一般签名；countersignature 强调与已有签名配套确认，不只是同一人把名字写得更好看。',('The form has a separate box for a countersignature.','表格有一个单独的副署栏。'),('She checked that the countersignature was present.','她确认文件上已有追加的确认签名。'),sources=['https://www.merriam-webster.com/dictionary/countersignature','https://en.wiktionary.org/wiki/countersignature#English']),
E('insignia','/ɪnˈsɪɡniə/','徽记；身份、军衔或荣誉标志','insignia 像制服上的条纹和徽章，一眼告诉别人“他属于哪个组织、是什么身份”。','借拉丁 īnsignia，是 īnsigne“徽记”的复数；其 in- 与 signum 组合表示带有标记，不是“不”的前缀。',D(INS,'insignia','身份、职衔等的识别标志'),'历史上是复数，现代英语也可当单数，并有 insignias 复数。日常最常见军队、组织、职位的徽记。','military insignia；rank insignia；an official insignia。','insignificant 的 in- 是否定；insignia 的 in- 不是，所以不能把 insignia 记成“没有标记”。',('The uniform carries the unit’s insignia on the shoulder.','制服肩部带着该单位的徽记。'),('The display explains the meaning of different rank insignia.','展板解释了不同军衔标志的含义。'),sources=['https://www.merriam-webster.com/dictionary/insignia','https://en.wiktionary.org/wiki/insignia#English']),
E('insigne','/ɪnˈsɪɡniː/','徽章；徽记〔较少用的单数形式〕','insigne 可以理解为一枚具体的身份标志，保留了更接近拉丁单数的外形。','借自拉丁 īnsigne，和复数 īnsignia 成对；不是英语 insignia 随意换最后一个字母造出的新意思。',D(INS,'insigne','保留拉丁单数外形的徽记名称'),'通常在较正式、历史或收藏说明中见到。现代一般用 insignia 或 badge 更常见。','a regimental insigne；an insigne of office。','insigne 与 insignia 的区别主要关乎历史单复数和实际用法，不表示两种不同材质的徽章。',('The museum acquired a bronze regimental insigne.','博物馆购藏了一枚青铜军团徽章。'),('An insigne of office hangs from the chain.','链子上挂着一枚职务徽记。'),sources=['https://www.merriam-webster.com/dictionary/insigne','https://en.wiktionary.org/wiki/insigne#English']),
E('ensign','英 /ˈensaɪn/；美 /ˈensən/','舰旗；旗帜；海军少尉','ensign 最初是让人辨认队伍或身份的旗号，后来也成为特定军官军衔的名称。','拉丁 īnsignia 经古法语 enseigne、中古英语 ensigne 传入，与较晚直接借入的 insignia 是同源异形词。',INS+[['古法语 enseigne → 中古英语 ensigne','旗帜、标志'],['英语：ensign','舰旗；由旗帜、执旗职务相关历史发展为军衔称呼']],'a naval ensign 可指舰旗；an ensign 在美国海军语境可指少尉。英美常见读音不同，不能只看拼写按 sign 读。','fly an ensign；the naval ensign；a newly commissioned ensign。','flag 是旗帜总称；ensign 通常有国家、军队或舰船身份标识等特定背景。',('The ship flew a naval ensign at the stern.','舰船在船尾升起了舰旗。'),('The young ensign joined the crew after training.','那名年轻海军少尉受训后加入了舰员队伍。'),sources=['https://en.wiktionary.org/wiki/ensign#English','https://www.merriam-webster.com/dictionary/ensign']),
E('signet','/ˈsɪɡnət/','小印章；图章戒指上的印章','signet 像把个人标记缩到一枚小印章上，可以戴在戒指上，随时压进封蜡留下身份印记。','借古法语 signet，是 signe“标志”的指小形式；现代不要按 sign /saɪn/ 直接加 -et 读。',S+[['古法语 signe + 指小词尾 → signet','标志 → 小印章'],['英语：signet','私人小印章；常嵌在戒指上']],'a signet ring 是图章戒指；历史文献中 signet 也可能指权威人士使用的特定印章。','a signet ring；press a signet into wax；a royal signet。','cygnet 是幼天鹅，与 signet 同音但不同源；seal 的印章义范围更广。',('The ring carried a signet engraved with the family emblem.','戒指上有一枚刻着家族徽记的小印章。'),('He pressed the signet into the warm wax.','他把小印章压进温热的蜡里。'),sources=['https://www.etymonline.com/word/signet','https://www.merriam-webster.com/dictionary/signet']),
E('signboard','英 /ˈsaɪnbɔːd/；美 /ˈsaɪnbɔːrd/','招牌；告示牌；标示牌','signboard 把抽象的标记放到一块实际的板上，让经过的人能看懂店名或指示。','sign + board，英语复合词；board 在这里是板，不是董事会。',D(SIGN,'sign + board → signboard','承载文字或图案标识的板'),'可放在店前，也可在路口、工地或公共场所；不一定是商业广告。','a shop signboard；a wooden signboard；read the signboard。','billboard 常是大型广告牌；signboard 更一般，尺寸和目的不限于广告。',('A wooden signboard marked the entrance to the farm.','一块木牌标出了农场入口。'),('The shop repainted its signboard before reopening.','商店重新开业前把招牌重漆了一遍。')),
E('signpost','英 /ˈsaɪnpəʊst/；美 /ˈsaɪnpoʊst/','路标；指示牌；标出方向；提示文章结构','signpost 像岔路口那根带箭头的杆：告诉你往哪走。文章里的提示句也能像路标一样帮读者跟上。','sign + post，post 在这里是柱、杆；名词又转为动词“立标指路”，并引申到组织信息。',D(SIGN,'sign + post → signpost','带指示牌的柱子 → 路标；指示方向、结构'),'follow the signposts 是顺着路标走；signpost an argument 是把论证的方向和层次说明白。','a signpost to；follow the signposts；signpost the main points。','signboard 只强调板上有标识；signpost 更突出指引到某处或某个论述方向。',('A signpost pointed us towards the lake.','路标指引我们往湖边走。'),('The introduction signposts the main stages of the argument.','引言交代了论证的主要步骤。')),
E('signposted','英 /ˈsaɪnpəʊstɪd/；美 /ˈsaɪnpoʊstɪd/','设有路标的；已清楚指明的','signposted 像路上的箭头都已经摆好，来的人能够知道该转向哪里。','signpost + -ed，动词过去分词；可用于道路，也可比喻内容的指引。',D(D(SIGN,'signpost','设路标、作指引'),'signposted','已经标出方向或层次的'),'clearly signposted 可说路线，也可说文章结构；well signposted 是路标、提示做得清楚。','clearly signposted；a signposted route；well signposted。','signed 也可在道路语境指有标牌；signposted 更明确突出方向指引，日常不表示签了名。',('The walking route is clearly signposted from the station.','从车站开始，步行路线就有清楚的路标。'),('Each stage of the report is carefully signposted.','报告对每个阶段都作了清楚的提示。'),sources=['https://en.wiktionary.org/wiki/signposted#English','https://www.oxfordlearnersdictionaries.com/definition/english/signpost_2']),
E('signposting','英 /ˈsaɪnpəʊstɪŋ/；美 /ˈsaɪnpoʊstɪŋ/','设置路标；指引；给文章或讲话提示结构','signposting 像一路放下提示：“先谈原因，接着看例子，最后讨论办法。”读者因此不会迷路。','signpost + -ing，动作名词；从真实路标扩展到文字、讲话及服务中的引导。',D(D(SIGN,'signpost','设路标、指明方向'),'signposting','提供路径、结构或去向指引'),'academic signposting 指学术写作中的结构提示；服务场景也可指引导人找到相关资源。','clear signposting；signposting language；improve signposting。','summary 是概括内容；signposting 主要告诉读者现在讲到哪里、接下来往哪走。',('Clear signposting helps readers follow a long argument.','清楚的结构提示能帮助读者跟上长篇论证。'),('Visitors complained about poor signposting in the park.','游客抱怨公园里的路标指引不清楚。'),sources=['https://en.wiktionary.org/wiki/signposting#English','https://www.oxfordlearnersdictionaries.com/definition/english/signposting']),
E('signage','/ˈsaɪnɪdʒ/','标识牌；标识系统〔总称〕','signage 把一个地方所有指示牌、名称牌等看作一套系统，像车站里从入口一直带你走到站台的那些标识。','sign + -age，英语中把相关标志看作整体的构词。',D(SIGN,'sign + -age → signage','一组或一套牌面标识'),'通常不可数：new signage、clear signage。一个具体的牌子一般说 a sign，不说 a signage。','clear signage；directional signage；digital signage。','signalling 是发出、传递信号的过程；signage 是标识的整体，可以是静态牌子或电子屏。',('The museum installed new signage near the entrance.','博物馆在入口附近安装了新标识。'),('Clear signage makes the station easier to navigate.','清楚的标识让人在车站里更容易找路。')),
E('seal','/siːl/','印章；封印；密封条；封闭、密封；海豹〔另源〕','本族的 seal 从印在蜡上的身份标记出发：蜡既留下印，也封住信，于是意思走到密封。海豹只是碰巧同拼写。','印章义经古法语 seel 来自拉丁 sigillum，是 signum 的指小形式；动词可由名词转用或承接法语 seeler。海豹义来自古英语 seolh，另属日耳曼语来源。',SEALV,'a wax seal 是蜡封；a rubber seal 是密封圈或密封条；seal an envelope 是封信；seal a deal 是把约定敲定。','a broken seal；seal a container；seal the deal；my lips are sealed。','stamp 强调盖印工具或动作；seal 常把身份确认与封闭联系起来。动物 seal 不参与本页的历史图。',('The letter bore a red wax seal.','信上带着一枚红色蜡封。'),('Please seal the container tightly after use.','使用后请把容器密封好。'),('A seal rested on the rock beside the water.','一只海豹趴在水边的岩石上休息。'),sources=['https://www.etymonline.com/word/seal','https://en.wiktionary.org/wiki/seal#English']),
E('sealed','/siːld/','封好的；密封的；已确定的','sealed 像盖子合紧、接缝封住，里面的东西不能轻易跑出，外面的东西也不容易进去。','seal + -ed；本条走封印、封闭这条词源支线。',D(SEALV,'seal → sealed','封闭完成；比喻事情已定'),'a sealed envelope 是封好的信封；sealed containers 是密封容器；fate was sealed 是命运或结局已定。','a sealed envelope；a sealed container；sealed packaging。','closed 只说关上；sealed 通常进一步表示封口、阻隔，或有封条等措施。',('The samples arrived in sealed containers.','样品装在密封容器里送到了。'),('She placed the sealed envelope on the desk.','她把封好的信封放到桌上。')),
E('sealing','/ˈsiːlɪŋ/','封口；密封；密封用的；猎捕海豹〔另源〕','本族的 sealing 是把开口或缝隙封住这件事，让水、空气或内容物不随意进出。','seal“封印、密封”+ -ing；同形的海豹捕猎义来自另一个动物名 seal，不能把那条历史混进来。',D(SEALV,'seal + -ing → sealing','进行密封；用于密封的'),'sealing wax 是封蜡；sealing tape 是封口胶带；检查语境才能辨别是否在讨论 seal“海豹”的行业史。','sealing wax；sealing tape；the sealing of a joint。','sealing /ˈsiːlɪŋ/ 与 ceiling“天花板”同音；拼写与来源不同。',('The worker applied sealing tape around the joint.','工人在接缝周围贴上了密封胶带。'),('The display includes a stick of traditional sealing wax.','展品中有一根传统封蜡。')),
E('sealer','英 /ˈsiːlə/；美 /ˈsiːlər/','封口机；密封材料；封口者；猎海豹者〔另源〕','sealer 是帮你把口封上的人、工具或材料：比如把袋口封紧的机器，或封住木材表面的涂层。','seal“封闭”+ -er；另有从动物 seal 形成的猎海豹者、猎海豹船等义，不属于标记这一支。',D(SEALV,'seal + -er → sealer','执行封口的人、装置或材料'),'a vacuum sealer 是真空封口机；wood sealer 是木材封闭保护材料。这个词不只指一个人。','a vacuum sealer；wood sealer；a bag sealer。','sealant 特别常指填缝密封材料；sealer 还可以指机器，二者不能在所有场景互换。',('The café uses a bag sealer for its coffee beans.','咖啡馆用封口机封装咖啡豆袋。'),('She applied a clear sealer to the wooden surface.','她在木面上涂了一层透明封闭涂层。')),
E('sealant','/ˈsiːlənt/','密封胶；密封材料','sealant 像填进缝里的一层屏障，把水和空气原本能钻过的空隙堵住。','seal + -ant，英语构词，用来命名发挥密封作用的材料。',D(SEALV,'seal + -ant → sealant','用于封住接缝、表面或开口的材料'),'常见于窗框、浴室接缝等；具体材料和使用方式因用途不同，不是所有 sealant 都是同一种胶。','apply sealant；silicone sealant；a waterproof sealant。','adhesive 重点是把东西粘在一起；sealant 重点是封住空隙，有些产品会兼具两种功能。',('The old sealant around the window had cracked.','窗户周围的旧密封胶开裂了。'),('They used a flexible sealant along the joint.','他们沿接缝使用了一种柔性密封材料。')),
E('unseal','/ʌnˈsiːl/','拆封；启封；解除封闭','unseal 像揭开封条、破开蜡封，让原来封着的东西重新能够打开或查看。','un-（解除、逆转动作）+ seal，英语构词；这里的 un- 表示把密封状态撤去。',D(SEALV,'un- + seal → unseal','拆开封印或解除封闭状态'),'unseal an envelope 是拆封；unseal records 可指正式解除文件的封存状态，使其可查阅。','unseal a container；unseal an envelope；unseal records。','open 是一般打开；unseal 特别说明此前有封口、封条或封存状态。',('She carefully unsealed the envelope.','她小心地拆开了信封。'),('The archive unsealed the collection after the restriction expired.','限制期满后，档案馆解除了这批资料的封存。'),sources=['https://www.etymonline.com/word/unseal','https://en.wiktionary.org/wiki/unseal#English']),
E('sigil','/ˈsɪdʒɪl/，也 /ˈsɪdʒəl/','符印；神秘符号；特定标记','sigil 像用一幅压缩的小图形代表身份、名称或力量；在奇幻作品里，常是一眼能认出的符印。','直接借拉丁 sigillum“小标记、印章”，与经过法语音变而来的 seal 同源异形；不是从英语 seal 改拼写。',D(SIGILLUM,'sigil','符印、标记；后来常用于神秘学与奇幻语境'),'现代常见于奇幻、神秘学讨论；某些编程语言也用 sigil 指加在名称前、提示类型等作用的符号。','a magical sigil；draw a sigil；a family sigil。','symbol 是符号总称；sigil 常是带身份、神秘传统或特定技术用途的图形标记。',('The fantasy novel gives each family a different sigil.','这部奇幻小说为每个家族设置了不同的符印。'),('The manuscript shows a circular sigil beside the name.','手稿在名字旁画了一个圆形符印。'),sources=['https://en.wiktionary.org/wiki/sigil#English','https://www.merriam-webster.com/dictionary/sigil']),
]
ROOT=dict(id='C1340',meaning='标记；让人识别、指明、表达',core='SIGN = A MEANINGFUL MARK',image='在纸上做一个记号：它可以说明“这是我”，也可以指明“这一份归你”，还可以画出“将来要做成这样”。',intro='拉丁语 signum 是让人辨认、读出意义的标记，signāre 是做记号、盖印。先掌握 sign 的记号与签名，再看 signal 怎样传信息、design 怎样标出计划、assign 怎样划定归属、significant 怎样从有含义走向有分量。更早的印欧词源有不同解释，本页不把“切刻”或“跟随”某一种理论画成定论。',forms='**sign-**：来自 signum / signāre。sign、design、assign 的 g 不发音，signal、signature、designation 中的 g 则发 /ɡ/，要跟着整词读音学。\n\n**signific-**：signum 与 facere 的构词支线，表示传达意义；significant、significance 有各自借入史。\n\n**sigill- / seal / sigil**：拉丁 sigillum“小标记、印章”衍生出直接借词 sigil 和经法语传播的 seal。\n\n**insign- / ensign**：拉丁 īnsigne、īnsignia 的直接借入与法语转借；这里的 in- 不是否定前缀。',branches=[['看懂标记与传递信号','sign / signal / signage / signpost'],['留下身份确认','signature / signatory / countersign / signet'],['表达意义与重要性','signify / significant / significance'],['先规划，再指定','design / redesign / designate / designation'],['给任务、权利安排归属','assign / assignment / assignee / consign / consignment'],['交还与无奈接受','resign / resignation / resigned'],['身份徽记与旗号','insignia / insigne / ensign'],['从封印走向封闭','seal / sealed / sealing / sealer / sealant / unseal / sigil']],contrasts='sign 是记号、迹象或签署动作；signature 是签名或鲜明特征；signal 强调信号。siggy 是 signature 的网络口语缩略。\n\ndesign 是规划、设计；designate 是指定某个人或用途。designation 的英语历史比现代动词 designate 更早，不能只看相似词尾就反推顺序。\n\nassignor 转出，assignee 接收；consignor 交货，consignee 收货。先画箭头，再记角色。\n\nresign 是辞去或放弃，resigned 是无奈接受；resignation 有辞职和认命两条常见义。\n\ninsignificant 的 in- 表示不，insignia 的 in- 不是否定。seal 的印章、密封义属于本族，海豹义另源。\n\nstatistically significant 不能直接等同“效果很大”；先判断是不是专门的统计用法。',practice='画一封信：写名字 signature、补一个确认签名 countersignature，再用蜡封 seal 封上；分别说出动作和结果。\n\n画出一项权利从 assignor 转到 assignee 的方向，再把运输中的 consignor / consignee 放在货物箭头两端。\n\n用 design a room 和 designate a room for meetings 各造一句，区分规划布局与指定用途。\n\n用 resigned 描写错过一班车后的表情，再用 resignation 写一份离职通知，体会两义共有的“放下”。',words=[x['word'] for x in W])
for x in W:
    if x['word'] in ('significant','significantly','significance','insignificant','insignificantly'):
        x['sources'].append('https://magazine.amstat.org/blog/2021/08/01/task-force-statement-p-value/')
    if x['word']=='consignor':
        x['sources'].append('https://www.collinsdictionary.com/dictionary/english/consignor')
    if x['word']=='insignificantly':
        x['sources'].append('https://www.oxfordlearnersdictionaries.com/definition/english/insignificantly')
